import { Type } from 'class-transformer';
import { IsBoolean, IsNumber, IsOptional, IsUUID, Max, Min } from 'class-validator';

// POST /posts/:id/view-heartbeat (B-093; Decision Log #384; docs/contest-spec.md section 9c).
//
// What the client reports, per beat, while a post is on screen: that it is ACTIVE (visible, the tab or
// app in the foreground, and for a video actually playing) and where the playhead is. It does NOT report
// how long it has watched: the server keeps the clock (view-session.util.ts).
export class ViewHeartbeatDto {
  // Generated by the client when the post comes on screen; one id per viewing session. It is bound to
  // the authenticated viewer and the post on the server, so another account cannot reuse it.
  @IsUUID()
  sessionId!: string;

  @IsBoolean()
  active!: boolean;

  // Video only: the playhead, in seconds. Required for a video (the server decides what a video is),
  // ignored for a photo or text.
  @IsOptional()
  @Type(() => Number)
  @IsNumber({ allowNaN: false, allowInfinity: false })
  @Min(0)
  @Max(86_400)
  positionSeconds?: number;

  // Video only: the media's length in seconds, as the player reports it. UNVERIFIABLE by the server
  // (it cannot open an arbitrary media URL), so it is only bounded; see the report for the residual risk.
  @IsOptional()
  @Type(() => Number)
  @IsNumber({ allowNaN: false, allowInfinity: false })
  @Min(0.5)
  @Max(86_400)
  durationSeconds?: number;
}
